// Preferred emoji names for common reactions
// These are the most standard/recognized names
const PREFERRED_EMOJI_NAMES: Record<string, string> = {
  "👍": "+1",
  "👎": "-1",
  "❤️": "heart",
  "😂": "joy",
  "😮": "open_mouth",
  "😢": "cry",
  "🙏": "pray",
  "😍": "heart_eyes",
  "😊": "blush",
  "🎉": "tada",
  "🔥": "fire",
  "👀": "eyes",
  "✅": "white_check_mark",
  "❌": "x",
};

// Reverse mapping: Unicode emoji -> emoji name (without colons)
// Built lazily on first access for performance
let reverseEmojiMap: Record<string, string> | null = null;

function getReverseEmojiMap(): Record<string, string> {
  if (!reverseEmojiMap) {
    reverseEmojiMap = {};
    
    // First, add preferred names
    for (const [emoji, name] of Object.entries(PREFERRED_EMOJI_NAMES)) {
      reverseEmojiMap[emoji] = name;
    }
    
    // Then add all other mappings (won't override preferred ones)
    for (const [name, emoji] of Object.entries(unicodeEmojiMap)) {
      if (!reverseEmojiMap[emoji]) {
        reverseEmojiMap[emoji] = name;
      }
    }
  }
  return reverseEmojiMap;
}

/**
 * Converts a Unicode emoji to a emoji name (without colons)
 * Example: "👍" -> "+1", "❤️" -> "heart"
 */
export function unicodeToEmojiName(unicodeEmoji: string): string | null {
  const reverseMap = getReverseEmojiMap();
  return reverseMap[unicodeEmoji] || null;
}
